export const articles: Article[] = [
  attachedArticleOne,
  ...legacyArticles.filter((article) => article.id !== "manona-1"),
];

export function getArticleBySlug(slug: string): Article | undefined {
  return articles.find((a) => a.slug === slug);
}

export function getArticlesByCategory(categorySlug: string): Article[] {
  return articles.filter(
    (a) => a.category.toLowerCase() === categorySlug.toLowerCase()
  );
}

// ── Dynamic categories ────────────────────────────────────────────────────
// Derived from all articles — legacy + seed. No static list.
function toSlug(label: string) {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

export function getCategories(): Category[] {
  const all = [
    ...articles.map((a) => a.category),
    ..._seed.map((a) => a.category),
  ];
  const seen = new Set<string>();
  const cats: Category[] = [];
  for (const label of all) {
    const slug = toSlug(label);
    if (!seen.has(slug)) {
      seen.add(slug);
      cats.push({ id: slug, slug, label, description: "" });
    }
  }
  return cats.sort((a, b) => a.label.localeCompare(b.label));
}

// categories export kept for backward-compat — callers should prefer getCategories()
export const categories = getCategories();

export function getAllArticlesByCategory(categorySlug: string) {
  const slug = categorySlug.toLowerCase();
  const legacy = articles.filter((a) => toSlug(a.category) === slug);
  const seed = _seed.filter((a) => toSlug(a.category) === slug);
  return { legacy, seed };
}

export function getSeriesById(id: string): Series | undefined {
  return series.find((s) => s.id === id);
}

export function getSeriesArticles(seriesId: string): Article[] {
  const s = getSeriesById(seriesId);
  if (!s) return [];
  return s.articleIds
    .map((id) => articles.find((a) => a.id === id))
    .filter(Boolean) as Article[];
}

export function getRelatedArticles(slugs: string[]): Article[] {
  return slugs
    .map((s) => getArticleBySlug(s))
    .filter(Boolean) as Article[];
}

export function searchArticles(query: string): Article[] {
  const q = query.toLowerCase();
  return articles.filter(
    (a) =>
      a.title.toLowerCase().includes(q) ||
      a.subtitle.toLowerCase().includes(q) ||
      a.excerpt.toLowerCase().includes(q) ||
      a.category.toLowerCase().includes(q) ||
      a.author.name.toLowerCase().includes(q)
  );
}

import { seedArticles as _seed } from "@/imports/articles";
import type { Article as ImportedArticle } from "@/imports/articles";

export function getSeedArticleBySlug(slug: string): ImportedArticle | undefined {
  return _seed.find((a) => a.slug === slug);
}

export function getAllSeedArticles(): ImportedArticle[] {
  return _seed;
}

export function searchSeedArticles(query: string): ImportedArticle[] {
  const q = query.toLowerCase();
  return _seed.filter(
    (a) =>
      a.title.toLowerCase().includes(q) ||
      a.excerpt.toLowerCase().includes(q) ||
      a.category.toLowerCase().includes(q) ||
      a.author.toLowerCase().includes(q)
  );
}
